        out (VDP_DATA), a
        VDP_REG 1, $C0          ; display on, no frame interrupt
        ld b, 0                 ; 256 pairs a turn of E
        ld c, VDP_DATA
; the second byte 12 T-states after the first
        ld e, 4
        ld d, BOX_FULL
